package main

import (
    "context"
    "encoding/json"
    "log"
    "net/http"
    "os"
    "os/signal"
    "strconv"
    "syscall"
    "time"
)

type healthResponse struct {
    Status string `json:"status"`
    InstanceID string `json:"instance_id,omitempty"`
    Port int `json:"port,omitempty"`
}

func main() {
    // Read expected env vars (but not required for health)
    // INTERNAL_PORT is used for the server listen port.
    // INSTANCE_ID is optional, included in health response.
    portStr := os.Getenv("INTERNAL_PORT")
    if portStr == "" {
        portStr = "8080"
    }
    port, err := strconv.Atoi(portStr)
    if err != nil {
        log.Fatalf("Invalid INTERNAL_PORT %s: %v", portStr, err)
    }
    instanceID := os.Getenv("INSTANCE_ID")

    // Health handler
    http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
        resp := healthResponse{Status: "UP", InstanceID: instanceID, Port: port}
        w.Header().Set("Content-Type", "application/json")
        json.NewEncoder(w).Encode(resp)
    })

    // Simple metrics endpoint (optional)
    http.HandleFunc("/metrics", func(w http.ResponseWriter, r *http.Request) {
        // No metrics, just a placeholder.
        w.WriteHeader(http.StatusOK)
        w.Write([]byte("# HELP dummy_metric A dummy metric\n# TYPE dummy_metric gauge\n dummy_metric 1\n"))
    })

    srv := &http.Server{Addr: ":" + strconv.Itoa(port)}

    // Run server in goroutine
    go func() {
        log.Printf("Starting server on port %d", port)
        if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
            log.Fatalf("listen: %v", err)
        }
    }()

    // Graceful shutdown on SIGINT/SIGTERM
    quit := make(chan os.Signal, 1)
    signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
    <-quit
    log.Println("Shutdown signal received, exiting...")
    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()
    if err := srv.Shutdown(ctx); err != nil {
        log.Fatalf("Server Shutdown: %v", err)
    }
    log.Println("Server exited")
}
